{
  "model": "Qwen3-TTS-12Hz-1.7B-Base",
  "input": {
    "text": "我刚才原话好像是“你怎么又不说一声，我一直在等”。这里面哪部分最容易像指责？",
    "language": "Chinese",
    "voice_setting": {
      "voice_id": "qwen3-profile-551ba559eee40fce",
      "seed": 1536181804,
